// 時間複雜度: O(log n)，空間複雜度: O(1)
function rangeBitwiseAnd(left, right) {
    while (right > left) {
        right &= right - 1; // Brian Kernighan：清掉最低位的 1
    }
    return right;
}

solutions.python:
# 方法一：同時右移找共同前綴
class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        shift = 0
        while left < right:
            left >>= 1
            right >>= 1
            shift += 1
        return left << shift


# 方法二：Brian Kernighan（推薦，更快）
class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        while left < right:
            right &= right - 1     # 消掉 right 最右邊的 1
        return right

